#pragma once
#include "Processor.h"
#include <NexumSidebar.h>
namespace nexumgate {
inline juce::Colour yellow(){return juce::Colour(0xffffd84d);}inline juce::Colour ink(){return juce::Colour(0xff182a36);}inline juce::Colour muted(){return juce::Colour(0xff91a7b9);}
class Theme:public nxf::MacroKnobTheme {
public:
 Theme(){using namespace juce;setColour(ResizableWindow::backgroundColourId,Colour(0xff12191d));setColour(TextButton::buttonColourId,Colour(0xff243442));setColour(TextButton::buttonOnColourId,yellow());setColour(TextButton::textColourOffId,Colour(0xffdce9f5));setColour(TextButton::textColourOnId,ink());setColour(ComboBox::backgroundColourId,Colour(0xff17242d));setColour(ComboBox::outlineColourId,Colour(0xff344650));setColour(ComboBox::textColourId,Colour(0xffdce9f5));setColour(ComboBox::arrowColourId,yellow());setColour(PopupMenu::backgroundColourId,Colour(0xff1e2b32));setColour(PopupMenu::textColourId,Colour(0xffdce9f5));setColour(PopupMenu::highlightedBackgroundColourId,yellow());setColour(PopupMenu::highlightedTextColourId,ink());setColour(Slider::thumbColourId,yellow());setColour(Slider::trackColourId,yellow());setColour(Slider::textBoxOutlineColourId,Colours::transparentBlack);setColour(Slider::textBoxBackgroundColourId,Colours::transparentBlack);setColour(Slider::textBoxTextColourId,Colour(0xffdce9f5));setColour(ToggleButton::textColourId,Colour(0xffdce9f5));setColour(ToggleButton::tickColourId,yellow());setColour(TextEditor::backgroundColourId,Colour(0xff101b24));setColour(TextEditor::textColourId,Colour(0xffdce9f5));setColour(TextEditor::outlineColourId,Colour(0xff344650));}
 void drawButtonBackground(juce::Graphics& g,juce::Button& b,const juce::Colour&,bool over,bool down)override{g.setColour(b.getToggleState()?yellow():juce::Colour(down?0xff334959:over?0xff2b4050:0xff243442));g.fillRoundedRectangle(b.getLocalBounds().toFloat().reduced(.5f),2);}
 void drawLinearSlider(juce::Graphics& g,int x,int y,int w,int h,float position,float min,float max,const juce::Slider::SliderStyle style,juce::Slider& slider)override{if((bool)slider.getProperties()["compactNumeric"])return;juce::LookAndFeel_V4::drawLinearSlider(g,x,y,w,h,position,min,max,style,slider);}
 juce::Font getTextButtonFont(juce::TextButton&,int)override{return juce::FontOptions(11.f,juce::Font::bold);}
 juce::Font getComboBoxFont(juce::ComboBox&)override{return juce::FontOptions(11.f);}
};
inline void text(juce::Graphics& g,juce::String value,juce::Rectangle<int> r,float size,juce::Colour colour,juce::Justification align=juce::Justification::centredLeft){g.setColour(colour);g.setFont(juce::FontOptions(size,juce::Font::bold));g.drawText(value,r,align,false);}
inline juce::var macroDescription(Processor& p,int index){auto* d=new juce::DynamicObject();d->setProperty("kind","Nexum.GateMacro");d->setProperty("macro",index);d->setProperty("instance",juce::String::toHexString((juce::int64)(intptr_t)&p));return juce::var(d);}
class TargetSlider:public juce::Slider,public juce::DragAndDropTarget {
 Processor& p;juce::String id;bool popup=false;juce::RangedAudioParameter* parameter;
 void menu(){using namespace juce;PopupMenu m;m.addSectionHeader(parameter->getName(60));int selected=p.selectedMacro.load();m.addItem(1,"Macro "+String(selected+1)+" assign",selected>=0);auto* link=p.macros()->find(id);m.addItem(2,"Remove macro link",link!=nullptr);m.addItem(3,"Macro range...",link!=nullptr);m.addSeparator();m.addItem(4,"Automation / Last tweaked");auto safe=Component::SafePointer<TargetSlider>(this);m.showMenuAsync(PopupMenu::Options().withTargetComponent(this),[safe](int result){if(!safe)return;if(result==1)safe->p.assignMacro(safe->p.selectedMacro.load(),safe->id);if(result==2)safe->p.removeMacroLink(safe->id);if(result==3){auto state=safe->p.macros();auto* link=state->find(safe->id);if(!link)return;auto* dialog=new AlertWindow("Macro range","Start and end in parameter units",MessageBoxIconType::NoIcon);dialog->addTextEditor("a",String(safe->parameter->convertFrom0to1(link->start)),"Start");dialog->addTextEditor("b",String(safe->parameter->convertFrom0to1(link->end)),"Ende");dialog->addButton("Save",1);dialog->addButton("Cancel",0);dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog](int result){if(safe&&result==1)safe->p.setMacroRange(safe->id,safe->parameter->convertTo0to1(dialog->getTextEditorContents("a").getFloatValue()),safe->parameter->convertTo0to1(dialog->getTextEditorContents("b").getFloatValue()));}),true);}if(result==4){if(auto* e=safe->findParentComponentOfClass<AudioProcessorEditor>())if(auto* context=e->getHostContext())if(auto menu=context->getContextMenuForParameter(safe->parameter)){menu->showNativeMenu(e->getLocalPoint(safe,safe->getLocalBounds().getCentre()));return;}safe->parameter->beginChangeGesture();safe->parameter->setValueNotifyingHost(safe->parameter->getValue());safe->parameter->endChangeGesture();}});}
public:
 TargetSlider(Processor& processor,juce::String parameterId):p(processor),id(parameterId),parameter(p.state.getParameter(id)){setComponentID("parameter:"+id);getProperties().set("parameterIndex",parameter->getParameterIndex());getProperties().set("fxAccent",(int)yellow().getARGB());setTooltip("Drag a macro link here / Shift-click: assign / Right-click: range & automation");}
 bool isInterestedInDragSource(const SourceDetails& d)override{int m=(int)d.description.getProperty("macro",-1);return d.description.getProperty("kind",{}).toString()=="Nexum.GateMacro"&&d.description.getProperty("instance",{}).toString()==juce::String::toHexString((juce::int64)(intptr_t)&p)&&m>=0&&m<(int)p.macros()->names.size()&&!dynamic_cast<juce::AudioParameterInt*>(parameter);}
 void itemDropped(const SourceDetails& d)override{if(isInterestedInDragSource(d))p.assignMacro((int)d.description["macro"],id);}
 void mouseDown(const juce::MouseEvent& e)override{popup=e.mods.isPopupMenu()||e.mods.isShiftDown();if(e.mods.isPopupMenu()){menu();return;}if(e.mods.isShiftDown()){p.assignMacro(p.selectedMacro.load(),id);return;}Slider::mouseDown(e);}
 void mouseDrag(const juce::MouseEvent& e)override{if(!popup)Slider::mouseDrag(e);}void mouseUp(const juce::MouseEvent& e)override{if(!popup)Slider::mouseUp(e);popup=false;}
 void paint(juce::Graphics& g)override{Slider::paint(g);auto routes=p.macros();if(auto* link=routes->find(id)){auto colour=juce::Colour(routes->colours[link->macro]);g.setColour(colour);g.setFont(juce::FontOptions(9.f,juce::Font::bold));g.drawText("M"+juce::String(link->macro+1),getWidth()-27,0,27,13,juce::Justification::centred);}}
};
class Knob:public juce::Component {
 juce::Label label;std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> link;
public:
 TargetSlider slider;
 Knob(Processor& p,juce::String id,juce::String name,bool light=true):slider(p,id){using namespace juce;setComponentID("control:"+id);addAndMakeVisible(slider);addAndMakeVisible(label);label.setText(name,dontSendNotification);label.setFont(FontOptions(10.f,Font::bold));label.setJustificationType(Justification::centred);label.setColour(Label::textColourId,light?ink():muted());label.setInterceptsMouseClicks(false,false);slider.setSliderStyle(Slider::RotaryHorizontalVerticalDrag);slider.setRotaryParameters(MathConstants<float>::pi*1.24f,MathConstants<float>::pi*2.76f,true);slider.setTextBoxStyle(Slider::TextBoxBelow,false,86,18);link=std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.state,id,slider);slider.setDoubleClickReturnValue(true,p.state.getParameter(id)->convertFrom0to1(p.state.getParameter(id)->getDefaultValue()));slider.setColour(Slider::textBoxTextColourId,light?ink():Colour(0xffdce9f5));slider.textFromValueFunction=[id](double v){if(id=="output"||id=="threshold")return String(v,1)+" dB";if(id=="tempo")return String(v,1)+" BPM";if(id=="cutoff")return v>=1000?String(v/1000,2)+" kHz":String(v,0)+" Hz";if(id=="attack"||id=="decay"||id=="release")return String(v*1000,v<.01?1:0)+" ms";return String(v*100,0)+" %";};slider.valueFromTextFunction=[id](const String& s){double v=s.getDoubleValue();if(id=="output"||id=="threshold"||id=="tempo")return v;if(id=="cutoff")return s.containsIgnoreCase("k")?v*1000:v;if(id=="attack"||id=="decay"||id=="release")return s.containsIgnoreCase("ms")?v/1000:v;return v/100;};slider.updateText();}
 ~Knob()override{link.reset();}
 void resized()override{slider.setBounds(0,0,getWidth(),getHeight()-16);label.setBounds(0,getHeight()-16,getWidth(),16);}
};
class MacroTile:public juce::Component {
 Processor& p;int index;nxf::MacroKnobTheme theme;juce::Slider slider;juce::Label label;
 class Handle:public juce::Component {MacroTile& owner;
 public:Handle(MacroTile& o):owner(o){}void paint(juce::Graphics& g)override{auto s=owner.p.macros();if(owner.index>=(int)s->names.size())return;text(g,juce::String(owner.index+1),{0,0,getWidth(),20},11,muted(),juce::Justification::centred);g.setColour(juce::Colour(s->colours[owner.index]));g.drawEllipse(getWidth()*.5f-8,26,16,16,1.3f);int count=0;for(auto& l:s->links)if(l.macro==owner.index)++count;text(g,juce::String(count),{0,26,getWidth(),16},10,juce::Colour(s->colours[owner.index]),juce::Justification::centred);}
 void mouseDown(const juce::MouseEvent& e)override{owner.p.selectedMacro.store(owner.index);if(e.mods.isPopupMenu()||e.y<getHeight()*.43f)owner.menu();}
 void mouseDrag(const juce::MouseEvent& e)override{if(e.getDistanceFromDragStart()<4||e.getMouseDownY()<getHeight()*.43f)return;if(auto* c=juce::DragAndDropContainer::findParentDragContainerFor(this))if(!c->isDragAndDropActive())c->startDragging(macroDescription(owner.p,owner.index),this);}
 }handle{*this};
 void menu(){using namespace juce;auto s=p.macros();if(index>=(int)s->names.size())return;PopupMenu m;m.addSectionHeader("Macro "+String(index+1));m.addItem(1,"Rename...");m.addItem(2,"Remove links");const String colours[]={"Yellow","Blue","Orange","Purple","Mint","Pink","Cyan","Lime"};for(int i=0;i<8;++i)m.addItem(10+i,colours[i]);auto safe=Component::SafePointer<MacroTile>(this);m.showMenuAsync(PopupMenu::Options().withTargetComponent(&handle),[safe](int result){if(!safe)return;auto state=safe->p.macros();if(safe->index>=(int)state->names.size())return;if(result==2)safe->p.removeMacroLinks(safe->index);if(result>=10&&result<18){const uint32 palette[]={0xffffd84d,0xff48aaff,0xffffa34d,0xffbc84ff,0xff51d5ac,0xfffa7298,0xff5bcfe0,0xffa6d46a};safe->p.setMacroInfo(safe->index,state->names[safe->index],Colour(palette[result-10]));}if(result==1){auto* dialog=new AlertWindow("Macro name","",MessageBoxIconType::NoIcon);dialog->addTextEditor("name",state->names[safe->index]);dialog->addButton("Save",1);dialog->addButton("Cancel",0);dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog](int result){if(!safe||result!=1)return;auto state=safe->p.macros();if(safe->index<(int)state->names.size())safe->p.setMacroInfo(safe->index,dialog->getTextEditorContents("name"),Colour(state->colours[safe->index]));}),true);}});}
public:
 MacroTile(Processor& processor,int i):p(processor),index(i){using namespace juce;setComponentID("control:macro"+String(i+1));addAndMakeVisible(slider);addAndMakeVisible(label);addAndMakeVisible(handle);handle.setComponentID("macro-drag:"+String(i+1));slider.setComponentID("parameter:macro"+String(i+1));slider.setLookAndFeel(&theme);slider.setSliderStyle(Slider::RotaryHorizontalVerticalDrag);slider.setTextBoxStyle(Slider::NoTextBox,false,0,0);slider.setRange(0,1,.0001);slider.setRotaryParameters(MathConstants<float>::pi*1.24f,MathConstants<float>::pi*2.76f,true);slider.setDoubleClickReturnValue(true,0);slider.onValueChange=[this]{p.setMacroValue(index,(float)slider.getValue());};slider.onDragStart=[this]{p.selectedMacro.store(index);if(index<8)p.state.getParameter("macro"+String(index+1))->beginChangeGesture();};slider.onDragEnd=[this]{if(index<8)p.state.getParameter("macro"+String(index+1))->endChangeGesture();};label.setFont(FontOptions(9.f,Font::bold));label.setJustificationType(Justification::centred);label.setInterceptsMouseClicks(false,false);refresh();}
 ~MacroTile()override{slider.setLookAndFeel(nullptr);}void refresh(){auto s=p.macros();if(index>=(int)s->names.size())return;if(!slider.isMouseButtonDown())slider.setValue(p.macroValue(index),juce::dontSendNotification);auto colour=juce::Colour(s->colours[index]);slider.getProperties().set("macroColour",(int)colour.getARGB());label.setColour(juce::Label::textColourId,colour);label.setText(s->names[index].isEmpty()?"MACRO "+juce::String(index+1):s->names[index],juce::dontSendNotification);repaint();}
 void paint(juce::Graphics& g)override{nxf::paintMacroTile(g,getWidth(),getHeight());}void resized()override{label.setBounds(0,getHeight()-15,getWidth(),15);slider.setBounds(6,1,getWidth()-35,getHeight()-17);handle.setBounds(getWidth()-26,1,25,getHeight()-17);}
};
class Sidebar:public nxf::SidebarFrame {
 Processor& p;juce::OwnedArray<MacroTile> tiles;
public:
 Sidebar(Processor& processor):SidebarFrame(2,"GATE",JucePlugin_VersionString),p(processor){setAccent(yellow());add.onClick=[this]{p.addMacro();refreshMacros();viewport.setViewPosition(0,juce::jmax(0,list.getHeight()-viewport.getHeight()));};}
 void refreshMacros()override{int count=p.macroCount();while(tiles.size()>count)tiles.removeLast();while(tiles.size()<count){auto* t=tiles.add(new MacroTile(p,tiles.size()));list.addAndMakeVisible(t);}int width=getWidth()-((count+1)*66>viewport.getHeight()?5:0);list.setSize(width,(count+1)*66);for(int i=0;i<count;++i){tiles[i]->setBounds(0,i*66,width,65);tiles[i]->refresh();}add.setBounds(0,count*66,width,66);list.repaint();}
};
}
